mapper.select:
select id, user_id, memory_type, content, source, scope, enabled, create_time, update_time
from user_agent_memory
where user_id = #{userId}

  and enabled = 1

order by update_time desc, id desc
limit #{limit}

select id, user_id, memory_type, content, source, scope, enabled, create_time, update_time
from user_agent_memory
where user_id = #{userId}
  and memory_type = #{memoryType}
limit 1

mapper.update:
update user_agent_memory
set enabled = 0,
    update_time = now()
where user_id = #{userId}
  and memory_type = #{memoryType}

mapper.delete:
delete from user_agent_memory
where user_id = #{userId}
  and memory_type = #{memoryType}
